def near(a,b,pad=0):
 d=np.linalg.norm(a[:,:3]-b[:,:3],axis=1);yaw=np.abs((a[:,5]-b[:,5]+np.pi/2)%np.pi-np.pi/2)
 return bool(np.all(d<=.012+pad)or(np.all(d<=.020+pad)and np.all(yaw<=.25+pad*10)))
