    roots.append({'root_id':rid,'environment':env,'split':'train'if env in 'AB'else'dev','dev_role':role,'family':fam,'target_color':c,'other_color':other,'replicate':rep,'seed':seed,'drawer_reset_m':0.,'layout':{'block_'+co:v[k].tolist()for k,co in enumerate(COLORS)},'branches':branches,'new_independent_root':True,'rejected_layout_candidates':reject});layouts.append((v,rid))
